package main

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"net/http"
	"os/exec"

	"github.com/gin-gonic/gin"
)

// Task represents a serialized job payload
type Task struct {
	Name    string
	Command string
	Args    []string
}

// PluginLoader allows dynamic task registration
type PluginLoader struct {
	Registry map[string]Task
}

func init() {
	gob.Register(Task{})
	gob.Register(PluginLoader{})
}

// ExecuteTask runs the deserialized task
func ExecuteTask(t Task) (string, error) {
	if t.Command == "" {
		return "", fmt.Errorf("empty command")
	}
	cmd := exec.Command(t.Command, t.Args...)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return string(output), err
	}
	return string(output), nil
}

// DeserializePayload decodes a gob-encoded Task from raw bytes
func DeserializePayload(data []byte) (*Task, error) {
	buf := bytes.NewBuffer(data)
	dec := gob.NewDecoder(buf)
	var task Task
	if err := dec.Decode(&task); err != nil {
		return nil, fmt.Errorf("deserialization failed: %w", err)
	}
	return &task, nil
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	// Internal task execution endpoint - accepts gob-encoded Task payloads
	// Used by internal job scheduler to dispatch work to this service
	r.POST("/api/v1/tasks/execute", func(c *gin.Context) {
		rawBody, err := c.GetRawData()
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "failed to read body"})
			return
		}

		if len(rawBody) == 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "empty payload"})
			return
		}

		// Validate content type for internal protocol
		contentType := c.GetHeader("Content-Type")
		if contentType != "application/x-gob" {
			c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "expected application/x-gob"})
			return
		}

		task, err := DeserializePayload(rawBody)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}

		// Log task for audit
		fmt.Printf("[AUDIT] Executing task: name=%s command=%s args=%v from=%s\n",
			task.Name, task.Command, task.Args, c.ClientIP())

		result, err := ExecuteTask(*task)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{
				"error":  err.Error(),
				"output": result,
			})
			return
		}

		c.JSON(http.StatusOK, gin.H{
			"status": "completed",
			"output": result,
		})
	})

	// Batch task submission for internal pipeline
	r.POST("/api/v1/tasks/batch", func(c *gin.Context) {
		// Placeholder for batch processing
		c.JSON(http.StatusNotImplemented, gin.H{"error": "not yet implemented"})
	})

	r.Run(":8080")
}
